"""Individually read frozen primary MAGMA methods; retain wrapper/model ambiguities."""
import gzip,hashlib,json,re,xml.etree.ElementTree as ET
from pathlib import Path
from collect_omics_review import paragraphs
ROOT=Path(__file__).resolve().parents[2]
USES={
'P019':('Defined previously known gene-trait associations using FUMA SNP2GENE/MAGMA and bulk TWAS, with FDR across traits; gene type all, custom MHC coordinates and symmetric50kb windows.','FUMA web filtering, MungeSumstats liftover, union with TWAS and cross-trait novelty/Fisher tests are separate. Preserve genome-build-specific MHC coordinates.'),
'P021':('Used MAGMA gene z-scores to weight disease genes for scDRS1.0.1; scDRS used200 matched control sets and gene-specific technical-noise weighting.','MAGMA provides gene association strength; scDRS cell scores, normalization and control sampling are separate algorithms.'),
'P024':('Mapped GWAS signals using35kb upstream/10kb downstream gene-body windows, then selected the top1000 MAGMA z-score weights for scDRS across multiple traits. The source names g1000_eur.bim and NCBI38.gene.loc.','Confirm actual SNP/gene coordinate builds instead of assuming filenames are compatible. APOE exclusion and downstream scDRS need explicit separate inputs/decisions.'),
'P035':('Used MAGMA.Celltyping in R for competitive genome-wide gene-set regression with 1000Genomes European LD,GRCh37 and35kb upstream/10kb downstream windows; averaged MAGMA and EWCE FDR-adjusted P-values for reported results.','The R wrapper, expression specificity and averaging adjusted P-values are separate from original MAGMA fitting; no FDR-control property is inferred for the reported average. Analyses were restricted to factors rather than QSNP results.'),
'P055':('Used MAGMA1.10 with a10kb annotation window and GRCh37/1000Genomes to produce gene z-scores, then selected top1000 genes for scDRS after human-to-mouse orthologue conversion; reused precomputed scores for many traits.','Distinguish newly computed from reused scores. MGI orthologue mapping and scDRS are separate; a10kb window description alone does not specify asymmetric orientation.'),
'P072':('Used MAGMA gene,competitive gene-set and gene-property analyses with an ancestry-proportioned custom1000Genomes panel,MSigDB7,GTEx8 and single-cell expression. Applied BH-FDR and conditional reanalysis of significant terms.','Construct the actual mixed-ancestry panel explicitly; a generic EUR label is insufficient. FUMA cell-type uploads/GENE2FUNC, reference expression preparation and the conditional term-retention rule are separate.'),
'P077':('Used MAGMA1.09b defaults with GRCh37 annotations and a precomputed European1000Genomes reference; genes and gene sets were tested with per-trait BH-FDR below0.05.','Current1.10 output is independently tested, not a1.09b parity claim. Reference/annotation bytes and the complete per-trait correction family must be supplied.'),
'P088':('Computed gene-level associations with MAGMA1.10 using European1000Genomes Phase3 LD, then supplied those results to PoPS0.2 feature-based prioritization for18383 genes.','MAGMA gene association is separate from PoPS joint feature modeling and its scores.'),
'P105':('Used MAGMA1.08 through FUMA1.3.8 with a1000Genomes EastAsian LD panel,19033 protein-coding genes and15485 MSigDB7 gene sets; compared analyses across annotation-window choices.','Supply the actual EAS panel and gene/set universes. Tissue/cell specificity, cross-window comparisons and historical FUMA/MAGMA defaults are separate from this current adapter.'),
'P107':('Used MAGMA1.08 through FUMA1.6.1 separately per meta-analysis stratum with0kb and35kb-upstream/10kb-downstream windows, after VEP rsID assignment and Picard build37 liftover.','Variant filtering/liftover and the reported BH/window-combination decision require separate reconstruction; retain the source description of its correction family without silently replacing it.'),
'P120':('Used MAGMA with1000Genomes European LD to generate gene-level associations/correlations and gene-feature enrichments as inputs to PoPS joint prioritization.','The PoPS feature library/joint model, V2G,MendelVar and FUSION/colocalization are separate workflows; MAGMA enrichment alone does not produce PoPS scores.'),
'P123':('Calculated MAGMA gene P-values/z-scores from cross-population MS GWAS and selected the top1000 genes outside the chromosome6:25-34Mb MHC region for scDRS1.0.2.','Keep the LD population/build and precise exclusion stage explicit. scDRS control scores,covariates and across-cell-type FDR are separate.'),
'P125':('Used MAGMA1.08 with35kb-upstream/10kb-downstream expanded gene boundaries and a European subset of the high-coverage1000Genomes reference.','The high-coverage reference edition differs from the older downloadable phase3 panel. Coordinate concordance, ancestry and historical options must be checked explicitly.'),
'P130':('Used MAGMA1.10 for NPE gene/gene-set analyses in FUMA/FAVOR pipelines; the source describes99.9percent variant-PC variance and an F test,with gene significance2.5e-6 and per-NPE Bonferroni pathway correction.','PC regression requires raw genotype/phenotype input in MAGMA; do not infer that model from P-only GWAS inputs. Reconcile the actual pipeline/design with the literal reported PC description. FUMA/FAVOR mapping and correction families remain separate.'),
'P131':('Used MAGMA gene-set P-values with Bonferroni correction to conservatively prefilter exploratory GSA-MiXeR2.1.1 enrichment results,alongside an unfiltered exploratory report.','GSA-MiXeR heritability modeling,AIC/enrichment selection and the combined reporting rule are distinct from MAGMA regression; no formal P-values are attributed to GSA-MiXeR alone.'),
'P150':('Used MAGMA1.08 through FUMA for SNP-wise-mean gene aggregation with European1000Genomes Phase3 LD and17674 protein-coding genes from Ensembl85; Bonferroni gene threshold2.83e-6.','The Methods heading also names gene-set/gene-property analyses; exact expression/set inputs require their own source reconstruction. Current1.10 is not full historical FUMA parity.'),
'P162':('Used MAGMA within FUMA1.3.7 for gene-set and tissue-expression enrichment across54GTEx8 tissues; independent-variant selection used FUMA r-squared0.05.','FUMA clumping and its prepared tissue-expression matrix are separate; the standalone MAGMA adapter requires explicit gene properties/background.'),
'P169':('Used MAGMA1.10 to define the top1000 CRC disease-associated genes from GWAS summary statistics for scDRS1.0.1 analyses of Tabula Sapiens and Gut Cell Atlas profiles.','Single-cell disease/control scores and empirical cell P-values are separate from the MAGMA gene-score stage.'),
'P182':('Used MAGMA1.10 gene-set enrichment of coexpression modules against osteoarthritis GWAS,with GRCh37 and35kb-upstream/10kb-downstream windows; applied FDR across modules and traits.','The paragraph describes distance to transcription start while also including gene-body windows; retain this wording for reconciliation. Module construction and cross-trait FDR are separate.'),
'P200':('Mapped meta-analysis SNP P-values to build38 NCBI protein-coding genes with symmetric10kb windows,European1000Genomes Phase3 LD and uniform GWAS sample size; used Bonferroni over annotated genes.','Declare the uniform total GWAS N and verify reference/SNP/gene coordinate builds. The statistical testing universe may differ from the count of initially annotated genes.'),
'P236':('Aggregated GWAS summary statistics into MAGMA gene-level z-scores as graph-node features,combined with GTEx7 and blood-atlas expression features; dropped nodes missing any required feature.','Graph construction/learning,expression preparation and node-removal criteria are separate from MAGMA association; gene Z is not an allele-effect direction.')}
EXTRA=[
('magma-celltyping','MAGMA.Celltyping',r'MAGMA\.Celltyping','R MAGMA expression/cell-type enrichment wrapper','P035','Used the MAGMA.Celltyping R package for competitive gene-set enrichment with European LD and strand/window-specific gene mapping.','The R wrapper and prepared expression inputs are not implemented by the standalone executable interface.'),
('ewce','EWCE',r'(?-i:EWCE)','Expression-weighted cell-type enrichment','P035','Compared EWCE and competitive MAGMA enrichment and averaged their FDR-adjusted P-values for the reported results.','EWCE enrichment and this reporting average remain separate from MAGMA.'),
('gsa-mixer','GSA-MiXeR',r'GSA[- ]MiXeR','Gene-set heritability enrichment','P131','Used GSA-MiXeR2.1.1 for exploratory gene-set heritability/enrichment,retaining AIC-positive sets with enrichment above1 and optionally filtering by MAGMA Bonferroni significance.','This is a distinct model from univariate/bivariate MiXeR and MAGMA gene-set P-values.'),
('favor','FAVOR',r'(?-i:FAVOR)','Variant annotation and gene-prioritization pipeline','P130','Used FAVOR alongside FUMA for variant/gene mapping and functional-enrichment analyses.','The paragraph does not identify every FAVOR scoring function; MAGMA does not reproduce FAVOR annotations.'),
('mendelvar','MendelVar',r'MendelVar','Mendelian disease-gene enrichment','P120','Used MendelVar on lead-variant regions plus/minus1Mb with European1000Genomes,matching thyroid/immune keywords in OMIM,HPO and Disease Ontology.','Ontology lookup/enrichment and its eligibility criteria are separate from MAGMA.')]
FUMA={pid:('Used the FUMA web workflow around the reported MAGMA analysis. '+USES[pid][0],'Only the original MAGMA statistical stage is exposed here. FUMA annotation,clumping,web resources/uploads and historical options remain separate.') for pid in ['P019','P072','P105','P107','P130','P150','P162']}
def main():
    evidence=json.loads((ROOT/'build/literature-review/magma-runtime/paper-evidence.json').read_text(encoding='utf-8'));by={e['paper_id']:e for e in evidence};papers={p['paper_id']:p for p in json.loads((ROOT/'docs/literature/omics-2023-2026/papers.json').read_text(encoding='utf-8'))}
    for e in evidence:
        raw=gzip.decompress((ROOT/'build/literature-review/xml'/f"{e['pmcid']}.xml.gz").read_bytes());assert hashlib.sha256(raw).hexdigest()==papers[e['paper_id']]['xml_sha256'];assert paragraphs(ET.fromstring(raw))[e['source']['paragraph_index']-1]==e['source']
    registry_path=Path(__file__).with_name('tool-registry.json');registry=json.loads(registry_path.read_text(encoding='utf-8'));ids={r['id'] for r in registry}
    for tid,name,pattern,role,*_ in EXTRA:
        if tid not in ids:registry.append(dict(id=tid,name=name,pattern=r'(?<![A-Za-z0-9_])(?:'+pattern+r')(?![A-Za-z0-9_])',role=role,current_coverage='missing',existing_source=None,coverage_note='Distinct source-named method/wrapper; integration and independent scientific validation pending.'))
    patterns={r['id']:r['pattern'] for r in registry};rows=[]
    def add(pid,tid,summary,note):
        e=by[pid];assert re.search(patterns[tid],e['source']['match_text'],re.I),(pid,tid);rows.append(dict(pmcid=e['pmcid'],doi=e['doi'],tool_id=tid,evidence_paragraph_sha256=hashlib.sha256(e['source']['text'].encode()).hexdigest(),use_summary=summary,implementation_scope_note=note))
    for pid,(summary,note) in USES.items():add(pid,'magma',summary,note)
    for tid,_,_,_,pid,summary,note in EXTRA:add(pid,tid,summary,note)
    for pid,(summary,note) in FUMA.items():add(pid,'fuma',summary,note)
    p=Path(__file__).with_name('reviewed-uses.json');review=json.loads(p.read_text(encoding='utf-8'));old={(r['pmcid'],r['tool_id']):r for r in review['reviews']};added=0
    for row in rows:
        key=row['pmcid'],row['tool_id']
        if key in old:assert old[key]==row,key
        else:review['reviews'].append(row);added+=1
    registry_path.write_text(json.dumps(registry,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');p.write_text(json.dumps(review,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');print(json.dumps(dict(added_reviews=added,total_reviews=len(review['reviews']),registry_names=len(registry))))
if __name__=='__main__':main()
